// Package parser implements V-compatible syntax parsing
package parser

import (
	"fmt"
	"strconv"

	"fv2-lang/internal/ast"
	"fv2-lang/internal/lexer"
)

// Parser converts tokens to AST
type Parser struct {
	tokens   []lexer.Token
	pos      int
	errors   []string
}

// New creates a new parser
func New(tokens []lexer.Token) *Parser {
	return &Parser{
		tokens: tokens,
		pos:    0,
		errors: []string{},
	}
}

// Parse parses tokens into an AST (with error recovery)
func (p *Parser) Parse() (*ast.Program, error) {
	var definitions []ast.Definition
	var mainBody []ast.Statement

	for !p.isAtEnd() {
		if p.match(lexer.TknEof) {
			break
		}

		// Handle import statements
		if p.check(lexer.TknImport) {
			def, err := p.parseImportStatement()
			if err != nil {
				p.errors = append(p.errors, err.Error())
				p.synchronize()
				continue
			}
			if def != nil {
				definitions = append(definitions, def)
			}
		} else if p.check(lexer.TknExtern) {
			// Handle extern function declaration
			def, err := p.parseExternDef()
			if err != nil {
				p.errors = append(p.errors, err.Error())
				p.synchronize()
				continue
			}
			if def != nil {
				definitions = append(definitions, def)
			}
		} else if p.check(lexer.TknFn) {
			// Handle regular function definition
			def, err := p.parseFunctionDef()
			if err != nil {
				p.errors = append(p.errors, err.Error())
				p.synchronize() // Error recovery: skip to next definition
				continue
			}
			if def != nil {
				definitions = append(definitions, def)
			}
		} else if p.check(lexer.TknType) {
			def, err := p.parseTypeDef()
			if err != nil {
				p.errors = append(p.errors, err.Error())
				p.synchronize() // Error recovery
				continue
			}
			if def != nil {
				definitions = append(definitions, def)
			}
		} else if p.check(lexer.TknStruct) {
			def, err := p.parseStructDef()
			if err != nil {
				p.errors = append(p.errors, err.Error())
				p.synchronize() // Error recovery
				continue
			}
			if def != nil {
				definitions = append(definitions, def)
			}
		} else {
			stmt, err := p.parseStatement()
			if err != nil {
				p.errors = append(p.errors, err.Error())
				p.synchronize() // Error recovery
				continue
			}
			if stmt != nil {
				mainBody = append(mainBody, stmt)
			}

// Package codegen implements code generation from AST to C
package codegen

import (
	"fmt"
	"strconv"
	"strings"

	"fv2-lang/internal/ast"
)

// Generator generates C code from an AST
type Generator struct {
	code            strings.Builder
	indent          int
	VarCounter      int
	functionStack   []string              // 현재 함수 스택
	varTypes        map[string]string     // Variable name → FV type (i64, f64, string, etc.)
	externFuncTypes map[string]string     // Extern function name → return type (i64, f64, etc.)
}

// New creates a new code generator
func New() *Generator {
	return &Generator{
		VarCounter:      0,
		functionStack:   []string{},
		varTypes:        make(map[string]string),
		externFuncTypes: make(map[string]string),
	}
}

// Generate generates C code from a program AST
func (g *Generator) Generate(program *ast.Program) (string, error) {
	// Header files
	g.writeLine("#include <stdio.h>")
	g.writeLine("#include <stdlib.h>")
	g.writeLine("#include <string.h>")
	g.writeLine("#include <stdbool.h>")
	g.writeLine("#include <ctype.h>")

	// Process imports and write additional headers
	for _, def := range program.Definitions {
		// DEBUG: Check type
		_ = fmt.Sprintf("%T", def)
		if imp, ok := def.(*ast.ImportStatement); ok {
			switch imp.Module {
			case "math":
				g.writeLine("#include <math.h>")
			case "stdio":
				// Already included
			case "string":
				// string functions in string.h already included
			case "stdlib":
				// stdlib.h already included
			case "http":
				// Custom HTTP library (if needed)
			case "io":
				// Custom I/O library
			default:
				// Unknown import - skip silently
			}
		}
	}
	g.writeLine("")

	// Forward declarations for functions (except main) and extern functions
	for _, def := range program.Definitions {
		switch d := def.(type) {
		case *ast.FunctionDef:
			if d.Name != "main" {
				g.writeFunctionDeclaration(d)
			}
		case *ast.ExternDef:
			g.writeExternDeclaration(d)
		}
	}
	g.writeLine("")

	// Type definitions (structs, etc)
	for _, def := range program.Definitions {
		switch d := def.(type) {
		case *ast.StructDef:
			g.writeStructDefinition(d)
		case *ast.TypeDef:
			g.writeTypeDefinition(d)
		}
	}
	g.writeLine("")

	// Function implementations
	var mainFunc *ast.FunctionDef
	for _, def := range program.Definitions {
		if fn, ok := def.(*ast.FunctionDef); ok {
			if fn.Name == "main" {
				mainFunc = fn
			} else {
				g.writeFunctionDefinition(fn)
				g.writeLine("")
			}
		}

