class FVCompiler {
  async compile(code, options) {
    const { optimizationLevel = 2 } = options;
    const tempId = Date.now();
    const fvFile = path.join(os.tmpdir(), `fv_${tempId}.fv`);
    const cFile = path.join(os.tmpdir(), `fv_${tempId}.c`);
    const binaryPath = path.join(os.tmpdir(), `fv_${tempId}`);
    const fv2 = '/data/data/com.termux/files/home/projects/fv2-lang-go/bin/fv2';

    try {
      // 1. FV 코드 저장
      fs.writeFileSync(fvFile, code);

      // 2. fv2로 C 코드 생성
      const startTime = Date.now();
      let cCode = '';
      try {
        cCode = execSync(`"${fv2}" "${fvFile}"`, {
          timeout: 10000,
          stdio: 'pipe',
          encoding: 'utf-8'
        });
      } catch (error) {
        return {
          success: false,
          language: 'fv',
          code,
          output: '',
          performance: { compileTime: 0, executionTime: 0, memoryUsage: 0, binarySize: 0 },
          errors: ['FV 컴파일 오류: ' + (error.message || 'Unknown error')]
        };
      }

      fs.writeFileSync(cFile, cCode);

      // 3. GCC로 C 코드 컴파일
      const gccCmd = `gcc -O${optimizationLevel} "${cFile}" -o "${binaryPath}" -lm`;
      execSync(gccCmd, { timeout: 30000, stdio: 'pipe' });

      const compileTime = Date.now() - startTime;

      // 4. 바이너리 실행
      let output = '';
      try {
        output = execSync(`timeout 5 "${binaryPath}"`, {
          encoding: 'utf-8',
          stdio: 'pipe'
        });
      } catch (error) {
        output = 'Execution timeout or error';
      }

      // 5. 바이너리 크기
      const stats = fs.statSync(binaryPath);
      const binarySize = Math.round(stats.size / 1024); // KB

      // 정리
      try {
        fs.unlinkSync(fvFile);
        fs.unlinkSync(cFile);
      } catch (e) {}

      return {
        success: true,
        language: 'fv',
        code,
        output: output.trim(),
        performance: {
          compileTime,
          executionTime: 0.001,
          memoryUsage: 1,
          binarySize
        },
        errors: []
      };
    } catch (error) {
      return {
        success: false,
        language: 'fv',
        code,
        output: '',
        performance: { compileTime: 0, executionTime: 0, memoryUsage: 0, binarySize: 0 },
        errors: [error.message]
      };
    }
  }
}

