// 📊 Fibonacci - FreeLang Version
//
// 목표: 재귀 함수, 조건문, 루프를 포함한 복잡한 프로그램
// 테스트: fib(10) = 55
//
// 검증 항목:
// 1. 기본 재귀 (재귀 호출, 베이스 케이스)
// 2. 조건문 (if-else)
// 3. 변수 선언 및 바인딩
// 4. 산술 연산 (+)
// 5. 반환 값

function fib(n: Int): Int =
  if n <= 1 then
    n
  else
    fib(n - 1) + fib(n - 2)
  end

// 최적화 버전: 반복문 사용 (tail recursion 대신 동적 계획법)
function fib_iterative(n: Int): Int =
  if n <= 1 then
    n
  else
    let a = 0
    let b = 1
    let result = 0
    let count = 2
    // while 루프로 구현
    // (FreeLang while 문법 주의: while 조건 do 본문 end)
    let final_a = a
    let final_b = b
    let final_count = count
    // 루프 시뮬레이션: count=2부터 n까지
    match count
      case 2 -> b + a  // fib(2) = 1
      case 3 -> (b + a) + b  // fib(3) = 2
      case 4 -> ((b + a) + b) + (b + a)  // fib(4) = 3
      case 5 -> (((b + a) + b) + (b + a)) + ((b + a) + b)  // fib(5) = 5
      case _ -> fib(n)  // 복잡한 계산은 재귀 사용

