```ts
// fn add(x: i64, y: i64) -> i64 { return x + y }
private parseFunctionDef(): AST.VFunction | null {
  if (!this.check('fn')) return null;
  this.advance();

  const name = this.current().text;
  this.advance();

  // 파라미터 파싱: (x: i64, y: i64)
  this.consume('(');
  const params = [];
  while (!this.check(')')) {
    const paramName = this.current().text;
    this.advance();
    this.consume(':');
    const paramType = this.current().text;
    this.advance();
    params.push({ name: paramName, typeAnnotation: paramType });
    if (!this.check(')')) this.consume(',');
  }
  this.consume(')');

  // 반환 타입: -> i64
  let returnType = 'void';
  if (this.check('->')) {
    this.advance();
    returnType = this.current().text;
    this.advance();
  }

  // 본문: { ... }
  this.consume('{');
  const body = [];
  while (!this.check('}')) {
    const stmt = this.parseStatement();
    if (stmt) body.push(stmt);
  }
  this.consume('}');

  return {
    type: 'VFunction',
    name,
    params,
    returnType,
    body
  };
}
```

### Step 2: 함수 정의 C 코드 생성 (1시간)

**파일**: `src/nexus/codegen/nexus-codegen.ts`

```ts
private genVFunctionDef(fn: AST.VFunction): void {
  // 함수 선언
  const returnType = this.mapVType(fn.returnType || 'void');
  const paramList = fn.params
    .map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`)
    .join(', ');

  this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
  this.indent++;

  // 함수 본문
  for (const stmt of fn.body) {
    if (stmt.type === 'ReturnStatement') {
      const expr = this.genVExpression(stmt.value);
      this.writeC(`return ${expr};`);
    } else {
      this.genVStatement(stmt);
    }
  }

  this.indent--;
  this.writeC(`}`);
  this.writeC('');
}
```

### Step 3: For-range 루프 (30분)

```ts
// for i in 0..10 { ... }
// for i in range(10) { ... }
private genVForRange(stmt: AST.ForStatement): void {
  // range(10) 해석 또는 0..10 구문
  const start = /* 분석 */;
